import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True


def is_multiply_prime(a):
    if a >= 100:
        return False
    for i in range(2, int(math.pow(a, 1/3)) + 1):
        if is_prime(i):
            for j in range(i, int(math.sqrt(a)) + 1):
                if is_prime(j):
                    for k in range(j, int(a / (i * j)) + 1):
                        if is_prime(k) and i * j * k == a:
                            return True
    return False
